from taf.internal.robot_typecasts import time_to_seconds

from ..util import wrap_result


class AutoConnectionInterface(object):

    def register_autoconnection(self, site_id, timeout=120):
        """Register autoconnection.

        :param string site_id: Site ID.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(site_id)

        self._api_client.execute_procedure("registerAutoconnection", {"siteId": site_id}, timeout)

    def update_trs_autoconnection_params(self, timeout=120, **parameters):
        """Update TRS autoconnection params.

        :param float timeout: Time to wait for positive procedure result.
        

        :Available parameters:
            * **eNBIpAddress** (string)
            * **netPrefixLength** (integer)
            * **defaultGateway** (string)
            * **vlanId** (integer)
            * **identificationServerIpAddress** (string)
            * **vnpGatewayIpAddress** (string)
            * **cmpServerIpAddress** (string)
            * **cmpServerPort** (integer)
            * **cmpSubjectName** (string)
            * **cmpDirectory** (string)
        """
        timeout = time_to_seconds(timeout)

        self._api_client.execute_procedure("updateTrsAutoconnectionParams", parameters, timeout)

    def get_autoconnection_status(self, timeout=10):
        """Get autoconnection status.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: autoConnectionStatus parameter of AUTOCONFIG object
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("getAutoconnectionStatus", {}, timeout)

    @wrap_result
    def get_trs_autoconnection_status(self, timeout=10):
        """Get TRS autoconnection status.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: object
        :return: FTM object with parameters: ipStatus, dhcpStatus, certificateStatus
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("getTrsAutoconnectionStatus", {}, timeout)
